get_cart.code:
final response = await client.carts.getCart('cart-7f3a9c2e1b');
final cart = (response.map as Map)['cart'] as Map;
for (final item in cart['items'] as List) {
  final product = (item as Map)['product'] as Map;
  print('${item['id']} ${product['name']} ${item['quantity']}');
}
final totals = cart['totals'] as Map;
print('${totals['subtotal']} ${totals['grand_total']}');

update_cart_item.code:
final response = await client.carts
    .updateCartItem('cart-7f3a9c2e1b', {'cart_item_id': 42, 'quantity': 2});
final cart = (response.map as Map)['cart'] as Map;
for (final item in cart['items'] as List) {
  print('${(item as Map)['id']} ${item['quantity']}');
}
print((cart['totals'] as Map)['subtotal']);

